import sys, math; sys.path.insert(0,'/home/claude/honglifecalc/build')
from enrich_lib import build, table, add_top
P='/ru/transportnyj-nalog.html'

# Moscow passenger-car rates, Закон г. Москвы от 09.07.2008 № 33 in the wording of Закон г. Москвы от 13.11.2024 № 21
# (verified 2026-11-28 on mos.ru consolidated PDF (ред. 01.11.2025) and on the text of law № 21 published by UFNS Moscow).
MSK={2025:[(100,13),(125,28),(150,35),(200,50),(225,72),(250,75),(1e12,150)],
     2026:[(100,14),(125,31),(150,35),(200,50),(225,75),(250,75),(1e12,150)]}
def rate(hp,y=2026):
    for h,v in MSK[y]:
        if hp<=h: return v
def tax(hp,m=12,k=1,y=2026,r=None):
    r=r or rate(hp,y); return math.floor(hp*r*m/12*k+0.5)
R=lambda x:f"{x:,}".replace(',',' ')+' ₽'

form='''<form class="card" id="form" onsubmit="return false"><h2>Ваши данные</h2><label class="f"><span>Мощность двигателя, л. с.</span><input id="hp" inputmode="decimal" value="150"><small>Смотрите в ПТС или СТС. Если указаны только кВт: л. с. = кВт × 1,35962.</small></label><label class="f"><span>Налоговый период (год владения)</span><select id="y"><option value="2026" selected>2026 год – платить до 1 декабря 2027 г.</option><option value="2025">2025 год – платить до 1 декабря 2026 г.</option></select></label><label class="f"><span>Полных месяцев владения в году</span><input id="m" inputmode="decimal" value="12"><small>Если машина была у вас весь год – 12.</small></label><label class="f"><span>Своя ставка региона, ₽ за л. с. (0 – ставки Москвы)</span><input id="cr" inputmode="decimal" value="0"></label><label class="chk"><input type="checkbox" id="lux"> Автомобиль из перечня Минпромторга (средняя стоимость от 10 млн ₽) – коэффициент 3</label></form>'''

calc='''function calc(){const MSKY={2025:[[100,13],[125,28],[150,35],[200,50],[225,72],[250,75],[Infinity,150]],2026:[[100,14],[125,31],[150,35],[200,50],[225,75],[250,75],[Infinity,150]]};
 const y=($('y')&&$('y').value)==='2025'?2025:2026,hp=Math.max(0,num('hp')),m=Math.min(12,Math.max(0,Math.round(num('m')))),k=$('lux').checked?3:1;let r=num('cr'),src='своя ставка';if(!r){src='ставка Москвы за '+y+' год';for(const [h,v] of MSKY[y]){if(hp<=h){r=v;break}}}
 if(!hp)return big('Транспортный налог',rub(0,0),'введите мощность двигателя');
 const t=Math.round(hp*r*m/12*k);
 return big('Транспортный налог за '+y+' год',rub(t,0),hp.toLocaleString('ru-RU')+' л. с. × '+r.toLocaleString('ru-RU')+' ₽'+(m<12?' × '+m+'/12':'')+(k>1?' × 3':''))+kv([['Ставка',r.toLocaleString('ru-RU')+' ₽ за 1 л. с. ('+src+')'],['Месяцев владения',m+' из 12'],['Повышающий коэффициент',k>1?'3':'нет'],['В месяц (в среднем)',rub(t/12,0)],['Срок уплаты','до 1 декабря '+(y+1)+' года','t']])+'<p class="note">Налог считают в полных рублях. Налоговая сама присылает уведомление. Ставки и льготы других регионов проверьте на сайте ФНС.</p>'}'''

ex=[]
for hp,lab in [(90,'Небольшой городской автомобиль'),(106,'Седан 1,6 л'),(150,'Кроссовер'),(249,'Мощный седан'),(300,'Внедорожник')]:
    ex.append([lab,f"{hp} л. с.",R(tax(hp,y=2025)),R(tax(hp))])
print(ex, tax(150,7), tax(400,12,3), tax(106), tax(106,y=2025), tax(150), tax(151))

base=[['до 100 л. с. включительно','13 ₽','14 ₽','15 ₽ в 2027 г., дальше растёт до 25 ₽ с 2032 г.'],
      ['свыше 100 до 125 л. с.','28 ₽','31 ₽','34 ₽ в 2027 г., 35 ₽ с 2028 г.'],
      ['свыше 125 до 150 л. с.','35 ₽','35 ₽','35 ₽'],
      ['свыше 150 до 200 л. с.','50 ₽','50 ₽','50 ₽'],
      ['свыше 200 до 225 л. с.','72 ₽','75 ₽','75 ₽'],
      ['свыше 225 до 250 л. с.','75 ₽','75 ₽','75 ₽'],
      ['свыше 250 л. с.','150 ₽','150 ₽','150 ₽']]

FAQ=[
("Как рассчитать транспортный налог на машину?","Умножьте мощность в лошадиных силах на ставку региона. Если машина была у вас не весь год, умножьте ещё на число месяцев владения ÷ 12. Пример для Москвы за 2026 год: 150 л. с. × 35 ₽ = 5 250 ₽."),
("Какой транспортный налог на 150 л. с. в Москве?","5 250 ₽ в год: 150 × 35 ₽. Ставка 35 ₽ одинакова для 2025 и 2026 годов. А у машины на 151 л. с. ставка уже 50 ₽, и налог – 7 550 ₽. Поэтому важна каждая лошадиная сила на границе."),
("До какого числа платить транспортный налог в 2026 году?","Налог за 2025 год нужно заплатить не позднее 1 декабря 2026 года. Налог за 2026 год – не позднее 1 декабря 2027 года. Налоговая присылает уведомление не позднее чем за 30 дней до срока."),
("Вырос ли транспортный налог в Москве?","Да, для части машин. За 2026 год ставка до 100 л. с. – 14 ₽ (было 13 ₽ за 2025 год), от 100 до 125 л. с. – 31 ₽ (было 28 ₽), от 200 до 225 л. с. – 75 ₽ (было 72 ₽). Для машины 106 л. с. налог вырос с 2 968 ₽ до 3 286 ₽."),
("Что делать, если машину купили или продали в середине года?","Налог считают только за месяцы, когда машина была зарегистрирована на вас. Введите число месяцев в калькулятор. Пример: 150 л. с. в Москве за 7 месяцев – 3 063 ₽. Как считается месяц покупки или продажи, смотрите в своём налоговом уведомлении."),
("Что такое повышающий коэффициент 3?","Это утроение налога для дорогих машин из перечня Минпромторга. Он действует для машин средней стоимостью от 10 до 15 млн ₽, если с года выпуска прошло не больше 10 лет, и от 15 млн ₽ – не больше 20 лет. Пример: 400 л. с. в Москве: 400 × 150 × 3 = 180 000 ₽."),
("Почему в моём регионе другая ставка?","Ставки и льготы устанавливает закон того региона, где зарегистрирована машина. Узнайте ставку своего региона и введите её в поле «Своя ставка»."),
]

art='''<h2 id="figures">Ставки транспортного налога в Москве</h2>
'''+table(['Мощность легкового автомобиля','За 2025 год, ₽ за л. с.','За 2026 год, ₽ за л. с.','Дальше'],base)+'''
<p class="note">Закон г. Москвы № 33 «О транспортном налоге» (в редакции Закона г. Москвы от 13.11.2024 № 21). Одна ставка применяется ко всей мощности машины.</p>
'''+table(['Правило','Что сказано'],[
 ['Срок уплаты','не позднее 1 декабря года, следующего за годом владения: за 2025 год – до 1 декабря 2026 г.'],
 ['Уведомление','налоговая присылает его не позднее чем за 30 дней до срока уплаты'],
 ['Коэффициент 3','легковые машины из перечня Минпромторга: 10–15 млн ₽ и не старше 10 лет; от 15 млн ₽ и не старше 20 лет'],
 ['Округление','налог в полных рублях: меньше 50 копеек отбрасывают, 50 копеек и больше – до рубля'],
 ['Кто устанавливает ставки и льготы','закон региона, где зарегистрирована машина']])+'''
<h2 id="ex">Примеры для Москвы</h2>
<div id="examples">'''+table(['Пример','Мощность','Налог за 2025 год','Налог за 2026 год'],ex)+'''</div>
<ul><li><b>Машина куплена в июне</b> (7 месяцев владения в 2026 году): 150 л. с. × 35 ₽ × 7/12 = <b>3 063 ₽</b>.</li>
<li><b>Дорогой внедорожник из перечня Минпромторга.</b> 400 л. с. × 150 ₽ × 3 = <b>180 000 ₽</b>.</li>
<li><b>Граница 150 л. с.</b> 150 л. с. – 5 250 ₽, а 151 л. с. – 7 550 ₽. Ставка меняется сразу для всей мощности.</li></ul>
<p class="note">Расчёты сделаны формулой этого калькулятора по ставкам Москвы.</p>
<h2 id="how">Как считать: простыми словами</h2>
<p>Пример: машина 106 л. с., Москва, весь 2026 год.</p>
<ul><li>Находим строку в таблице: свыше 100 до 125 л. с. – <b>31 ₽</b> за каждую лошадиную силу.</li>
<li>Умножаем: 106 × 31 = <b>3 286 ₽</b> за год.</li></ul>
<p><b>Налоговая база</b> – это то, с чего считают налог. Для машины это мощность двигателя в лошадиных силах (л. с.). <b>Ставка</b> – сколько рублей платят за одну л. с.</p>
<p>Формула: налог = мощность × ставка × (месяцев владения ÷ 12) × повышающий коэффициент.</p>
<h2 id="tips">Советы и частые ошибки</h2>
<ul><li><b>Выберите правильный год.</b> В декабре 2026 года платят налог за 2025 год – по ставкам 2025 года.</li>
<li><b>Проверьте ставку своего региона.</b> В калькуляторе по умолчанию ставки Москвы.</li>
<li><b>Посмотрите льготы.</b> Их устанавливает регион, условия везде разные. Если льготы нет в уведомлении, подайте заявление через личный кабинет, МФЦ или налоговую.</li>
<li><b>Не ждите письма.</b> Если уведомление не пришло, проверьте личный кабинет налогоплательщика.</li></ul>
<h2 id="faq" style="margin-top:22px">Частые вопросы</h2>'''+''.join(f'<h3>{q}</h3><p>{a}</p>' for q,a in FAQ)+'''
<p class="note">Источники (проверено 28 ноября 2026 г.): <a href="https://www.mos.ru/upload/documents/files/6513/ZakongMoskviot09072008N33(redot01112025).pdf" rel="nofollow">Закон г. Москвы от 09.07.2008 № 33 «О транспортном налоге» (ред. от 01.11.2025), mos.ru</a>; <a href="https://www.nalog.gov.ru/html/sites/www.rn77.nalog.ru/2024/4kv2024/ZM21.pdf" rel="nofollow">Закон г. Москвы от 13.11.2024 № 21 (УФНС по г. Москве)</a>; <a href="https://www.nalog.gov.ru/nu/" rel="nofollow">ФНС России – налоговое уведомление 2026</a>; <a href="https://www.nalog.gov.ru/html/sites/www.rn87.nalog.ru/2025/2026/3011125.pdf" rel="nofollow">Перечень легковых автомобилей средней стоимостью от 10 млн рублей (2026 год)</a>; <a href="https://www.nalog.gov.ru/html/sites/www.rn24.nalog.ru/buklet/bukl_tr2024.pdf" rel="nofollow">ФНС России – памятка «Транспортный налог физических лиц»</a>. Расчёты сделаны формулой этого калькулятора.</p>'''

out=build(P,'Транспортный налог 2026 – калькулятор по ставкам Москвы',
 'Посчитайте транспортный налог за 2025 и 2026 год: новые ставки Москвы, неполный год владения, коэффициент 3, срок уплаты до 1 декабря. Примеры.',
 art,FAQ,form=form,calc=calc)
s=open(out,encoding='utf-8').read()
s=s.replace('const MSK=[[100,12],[125,25],[150,35],[175,45],[200,50],[225,65],[250,75],[Infinity,150]];\n','',1)
open(out,'w',encoding='utf-8').write(s)
add_top(out,[('Автор','Hong Life Calculators'),('Проверено','28 ноября 2026 г.'),('Источники','Закон г. Москвы № 33, ФНС России')],
 [('form','Калькулятор'),('figures','Ставки и правила'),('ex','Примеры'),('how','Как считать'),('tips','Советы'),('faq','Частые вопросы')],'Содержание',('#examples','ru'))
print(out)
